insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0005-0000-4000-8000-00000000000d', 'en', null, 'Ancient & Imperial China: History & Civilization', 'A guided tour of more than three thousand years of Chinese history, from the Neolithic villages of the Yellow River to the fall of the last emperor in 1912. The course follows the dynasties in order and weaves together politics, philosophy, invention, and daily life. Structure and dates adapted from Wikipedia, the free encyclopedia (CC BY-SA 4.0).', null, 'foundations', 53, true, 'humanities', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0005-0000-4000-8000-00000000000d', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Which river valley is usually called a cradle of early Chinese civilization?","options":["The Ganges","The Yellow River (Huang He)","The Mekong","The Tigris"],"answer":1,"explanation":"Neolithic farming cultures clustered along the loess soils of the Yellow River in the north - see ''Early China''."},{"prompt":"The doctrine the Zhou used to justify overthrowing the Shang was the...","options":["Mandate of Heaven","divine right of kings","social contract","Mandate of the People"],"answer":0,"explanation":"The Mandate of Heaven held that Heaven granted a just ruler the right to rule and withdrew it from a corrupt one."},{"prompt":"Confucius, whose teachings stressed ritual, learning, and filial piety, lived roughly in the...","options":["200s CE","500s BCE","1300s CE","100s BCE"],"answer":1,"explanation":"Confucius lived about 551 to 479 BCE, during the Zhou-era Spring and Autumn period."},{"prompt":"The ruler who unified the warring states in 221 BCE and took the title First Emperor was...","options":["Liu Bang","Kublai Khan","Qin Shi Huang","Han Wudi"],"answer":2,"explanation":"The king of Qin completed the conquest in 221 BCE and named himself Qin Shi Huang, the First Emperor."},{"prompt":"The overland trade routes linking Han China with Central Asia and beyond are known as the...","options":["Grand Canal","Silk Road","Royal Road","Spice Islands"],"answer":1,"explanation":"The Silk Road opened under Emperor Wu of Han after the missions of the envoy Zhang Qian."},{"prompt":"Which sequence lists these dynasties in correct chronological order?","options":["Tang, Song, Yuan, Ming","Song, Tang, Ming, Yuan","Yuan, Ming, Tang, Song","Ming, Yuan, Song, Tang"],"answer":0,"explanation":"Tang (618 to 907), Song (960 to 1279), Yuan (1271 to 1368), then Ming (1368 to 1644)."},{"prompt":"The last imperial dynasty of China, which ended in 1912, was the...","options":["Ming","Han","Qing","Tang"],"answer":2,"explanation":"The Manchu-led Qing was the final dynasty; the child emperor Puyi abdicated in 1912 - see ''The Qing and the end''."}]}'::jsonb, null, 10),
  (2, 'Early China: the Yellow River, Shang and Zhou', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Place the first Chinese states in order and explain the Mandate of Heaven, the idea that shaped Chinese politics for three thousand years. Warm-up: from the diagnostic, which river anchored early northern Chinese farming, and why would fertile but flood-prone soil push villages toward organized, cooperative rule?"},{"heading":"The idea","text":"Chinese civilization grew along the Yellow River, where Neolithic cultures such as the Yangshao (about 5000 to 3000 BCE) farmed millet in rich loess soil. Tradition names the Xia as the first dynasty, about 2070 to 1600 BCE, though its records are legendary. The Shang dynasty, about 1600 to 1046 BCE, is the first confirmed by writing: priests carved questions on oracle bones, and artisans cast ritual bronze vessels of astonishing skill. Around 1046 BCE the Zhou overthrew the Shang and ruled longer than any later house, to 256 BCE. To explain their victory the Zhou announced the Mandate of Heaven: Heaven blesses a just ruler and withdraws its favor, through floods, famine, or revolt, from a cruel one. A fallen dynasty had simply lost the Mandate, and a rising one had gained it. This single idea let every later rebellion claim legitimacy."},{"heading":"Key events and figures","text":"The Shang capital at Anyang has yielded tens of thousands of inscribed oracle bones, our earliest Chinese texts, along with royal tombs and horse-drawn chariots. The Zhou period split into the Western Zhou (1046 to 771 BCE), when kings held real power from their western capital, and the Eastern Zhou (771 to 256 BCE), after the court fled east to Luoyang. The Eastern Zhou is further divided into the Spring and Autumn period (about 771 to 476 BCE) and the Warring States period (about 475 to 221 BCE), when central authority collapsed and rival states fought for supremacy. That very disorder, as you will see next, forced thinkers to ask how a good society should be run."},{"heading":"Your turn","text":"1) Name the first dynasty confirmed by written records. 2) What were oracle bones used for? 3) Which dynasty introduced the Mandate of Heaven? 4) Put in order: Warring States, Western Zhou, Spring and Autumn. 5) Why was the Mandate useful to rebels? Answers: 1) the Shang. 2) divination - rulers asked questions, which priests carved onto bone or shell. 3) the Zhou. 4) Western Zhou, then Spring and Autumn, then Warring States. 5) it let a successful rebel claim the old ruler had lost Heaven''s favor and that he now held it."},{"heading":"Common mistakes and exit ticket","text":"Mistake: treating the Xia as firmly historical - it is traditional and not yet proven by contemporary writing, unlike the Shang. Mistake: thinking the Zhou were a short dynasty; they lasted roughly eight centuries, longer than any later house, even though their later kings were weak. Exit: (a) Which river valley cradled early Chinese civilization? (b) In one sentence, what does the Mandate of Heaven claim? Answers: the Yellow River; Heaven grants the right to rule to a just leader and strips it from an unjust one, so a dynasty''s fall proves it lost the Mandate."}]}'::jsonb, null, 13),
  (3, 'The Hundred Schools of Thought', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Tell apart the three traditions that still shape East Asian thought - Confucianism, Daoism, and Legalism - and say what problem each tried to solve. Warm-up: the Warring States were centuries of war between rival states. If you were advising a ruler then, would you bet on kindness, on stepping back, or on strict law to restore order?"},{"heading":"The idea","text":"The chaos of the Eastern Zhou produced a burst of competing philosophies later called the Hundred Schools of Thought. Confucius (about 551 to 479 BCE) taught that social harmony flows from virtue, ritual, education, and respect within relationships, above all the duty of children to parents, called filial piety. A good ruler leads by moral example, not force. Daoism, linked to the legendary Laozi and the text Dao De Jing, urged people to live in harmony with the Dao, the natural way, and to govern through wu wei, effortless non-interference. Legalism took the opposite view: people are selfish, so order needs strict, clearly published laws with harsh punishments and firm rewards. Confucianism asked rulers to be good; Legalism asked them to be feared; Daoism asked them to do less. Each answered the same question - how to end the violence - in a different voice."},{"heading":"Key events and figures","text":"Confucius wandered from state to state seeking a ruler who would adopt his ideas; he failed in his lifetime but his students collected his sayings in the Analects. His follower Mencius (about 372 to 289 BCE) argued human nature is basically good. The Daoist Zhuangzi wrote playful parables mocking rigid rules. The Legalist thinker Han Feizi (died 233 BCE) systematized the doctrine of law, method, and power, and his ideas were adopted by the state of Qin. Legalism, as you will see, helped Qin conquer its rivals and unify China - but its harshness also helped the Qin fall quickly. Confucianism, by contrast, would become the official philosophy of the state for two thousand years."},{"heading":"Your turn","text":"1) Which thinker stressed ritual, education, and filial piety? 2) What does wu wei mean? 3) Which school favored strict laws and harsh punishments? 4) Which school did the state of Qin adopt? 5) In which book are Confucius''s sayings preserved? Answers: 1) Confucius. 2) effortless action or non-interference, the Daoist ideal of governing by not forcing things. 3) Legalism. 4) Legalism. 5) the Analects."},{"heading":"Common mistakes and exit ticket","text":"Mistake: confusing Daoism''s call to step back with Confucianism''s call to actively cultivate virtue and ritual - they point in different directions. Mistake: assuming the school that won the war, Legalism, also won the long run; in fact Confucianism became the lasting state philosophy while Legalism was blamed for Qin cruelty. Exit: (a) Name the three major schools. (b) Which one became the enduring official philosophy of imperial China? Answers: Confucianism, Daoism, Legalism; Confucianism."}]}'::jsonb, null, 14),
  (4, 'The first unification: Qin Shi Huang', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how the Qin created the first unified Chinese empire in 221 BCE, and judge why so powerful a dynasty collapsed in only fifteen years. Warm-up: the Qin used Legalist methods. What might be the strength, and the danger, of running an empire on strict law and heavy punishment?"},{"heading":"The idea","text":"After centuries of Warring States conflict, the western state of Qin, organized on Legalist principles, conquered its rivals one by one and completed unification in 221 BCE. Its king declared himself Qin Shi Huang, the First Emperor, inventing a title that lasted until 1912. He forged a single realm from many states by standardizing the written script, coins, weights, measures, and even axle widths so carts fit the same ruts. He divided the land into centrally governed commanderies rather than feudal fiefs, built roads, and connected and extended earlier northern defensive walls into an early version of the Great Wall. Yet the same Legalist severity that enabled these feats - forced labor, heavy taxes, and the burning of books that challenged the state - made the regime hated. The First Emperor died in 210 BCE, and the Qin fell by 206 BCE, barely outliving its founder."},{"heading":"Key events and figures","text":"Qin Shi Huang is remembered for three colossal projects. The early Great Wall linked existing ramparts to guard the northern frontier against nomadic raiders; later dynasties, especially the Ming, rebuilt most of what stands today. His vast tomb complex near Xian held the Terracotta Army, thousands of life-sized clay soldiers, horses, and chariots, each face distinct, buried to guard him in the afterlife and rediscovered by farmers in 1974. He also obsessively sought an elixir of immortality. After his death a succession crisis and widespread revolts - led in part by the commoner Liu Bang - toppled the dynasty. Liu Bang won the ensuing civil war and founded the Han, which kept Qin''s unified structure while softening its harsh rule."},{"heading":"Your turn","text":"1) In what year was China first unified under the Qin? 2) What title did the Qin king take? 3) Name two things he standardized. 4) What is the Terracotta Army? 5) Why did the Qin fall so fast? Answers: 1) 221 BCE. 2) First Emperor, Qin Shi Huang. 3) any two of: the writing script, coins, weights, measures, axle widths. 4) thousands of life-sized clay soldiers buried to guard his tomb near Xian. 5) its harsh Legalist rule - heavy taxes, forced labor, and repression - sparked revolts soon after his death in 210 BCE."},{"heading":"Common mistakes and exit ticket","text":"Mistake: crediting Qin Shi Huang with the Great Wall you see in photographs - most surviving brick wall is Ming work from more than 1,500 years later; the Qin wall was earlier and largely of rammed earth. Mistake: assuming a strong, efficient state is automatically stable; Qin power bred resentment that destroyed it in about fifteen years. Exit: (a) Which dynasty followed and replaced the Qin? (b) What founding idea of government did the Qin pioneer that every later dynasty kept? Answers: the Han; a centralized empire under a single emperor with standardized administration."}]}'::jsonb, null, 14),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"The Mandate of Heaven was first used to justify the rise of which dynasty?","options":["The Shang","The Zhou","The Qin","The Han"],"answer":1,"explanation":"The Zhou announced the Mandate to explain their overthrow of the Shang around 1046 BCE."},{"prompt":"The earliest Chinese writing we have survives mainly on...","options":["silk scrolls","paper documents","oracle bones from the Shang","printed books"],"answer":2,"explanation":"Shang priests carved divination questions onto turtle shells and ox bones at Anyang."},{"prompt":"Which philosophy taught that order comes from strict laws and harsh punishments?","options":["Confucianism","Daoism","Legalism","Buddhism"],"answer":2,"explanation":"Legalism, systematized by Han Feizi, was adopted by the state of Qin."},{"prompt":"China was first unified into a single empire in which year?","options":["221 BCE","206 CE","1046 BCE","618 CE"],"answer":0,"explanation":"The state of Qin completed its conquests in 221 BCE under the future First Emperor."},{"prompt":"The thousands of life-sized clay figures found near Xian are called the...","options":["oracle bones","Terracotta Army","Forbidden City guards","Silk Road statues"],"answer":1,"explanation":"The Terracotta Army was buried to guard the tomb of Qin Shi Huang and rediscovered in 1974."},{"prompt":"Which tradition became the lasting official philosophy of imperial China?","options":["Legalism","Daoism","Confucianism","Mohism"],"answer":2,"explanation":"Though Qin ran on Legalism, Confucianism became the enduring philosophy of the state from the Han onward."}]}'::jsonb, null, 8),
  (6, 'The Han dynasty and the Silk Road', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe how the Han built a lasting empire and opened the Silk Road, and explain why Chinese people still call themselves the Han. Warm-up: the Qin fell for being too harsh. If you founded the next dynasty, what would you keep from the Qin, and what would you soften?"},{"heading":"The idea","text":"The Han dynasty (206 BCE to 220 CE) kept the unified Qin structure but governed more gently and embraced Confucianism as its guiding philosophy, training officials in the Confucian classics. It was so successful and long-lived that the Chinese majority ethnic group still calls itself the Han. The dynasty split in two: the Western or Former Han (206 BCE to 9 CE), interrupted by the short Xin regime of Wang Mang (9 to 23 CE), and the Eastern or Later Han (25 to 220 CE). Under Emperor Wu (Han Wudi, who ruled 141 to 87 BCE) the empire expanded far to the west and south. It was Han Wudi who sent the envoy Zhang Qian into Central Asia, and those missions opened the trade and diplomatic routes we now call the Silk Road, linking China to India, Persia, and ultimately the Roman world."},{"heading":"Key events and figures","text":"The Silk Road was not one road but a web of caravan routes carrying Chinese silk westward and bringing back horses, glass, and new ideas - including, later, Buddhism from India. Along it moved not only goods but religions, technologies, and disease. The Han also saw a key invention: around 105 CE the court official Cai Lun refined papermaking into a cheap, practical form, a breakthrough that would transform record-keeping and later printing. The Han promoted learning, compiled the first great history by Sima Qian, and built a professional bureaucracy. After 220 CE the empire fragmented into the Three Kingdoms and centuries of division, until the short Sui dynasty (581 to 618) reunified China and dug the Grand Canal, setting the stage for the Tang."},{"heading":"Your turn","text":"1) Which philosophy did the Han adopt to train its officials? 2) What major group still takes its name from this dynasty? 3) Who sent Zhang Qian west, opening the Silk Road? 4) Name one thing that traveled east along the Silk Road. 5) What did Cai Lun refine around 105 CE? Answers: 1) Confucianism. 2) the Han, China''s majority ethnic group. 3) Emperor Wu of Han, Han Wudi. 4) Buddhism (or horses, glass, new ideas). 5) papermaking."},{"heading":"Common mistakes and exit ticket","text":"Mistake: imagining the Silk Road as a single paved highway - it was a shifting network of caravan tracks across deserts and mountains. Mistake: dating paper to the Tang or Song; practical paper was a Han achievement under Cai Lun, around 105 CE, long before printing matured. Exit: (a) Give the rough span of the Han dynasty. (b) What connected Han China to Persia and Rome? Answers: about 206 BCE to 220 CE; the Silk Road trade network."}]}'::jsonb, null, 14),
  (7, 'The Tang and Song golden ages', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain why the Tang and Song are called golden ages, name the Four Great Inventions, and describe the civil-service examination. Warm-up: how might a country choose its officials by talent rather than birth, and what fair test could it use?"},{"heading":"The idea","text":"After the Sui reunified China, the Tang dynasty (618 to 907) and later the Song dynasty (960 to 1279) presided over golden ages of wealth, art, and invention. The Tang capital Changan was among the largest cities on Earth, a cosmopolitan hub of the Silk Road where Buddhism flourished and poetry reached its height - Li Bai and Du Fu are still revered as the greatest Chinese poets. The Song, though militarily weaker, was dazzlingly inventive and commercial, with bustling cities, paper money, and gunpowder weapons. Both dynasties built up the civil-service examination: candidates studied the Confucian classics and sat grueling written exams, and those who passed became scholar-officials. In principle this opened government to talent rather than noble birth, and it created the class of learned administrators, sometimes called mandarins, who ran China for a thousand years."},{"heading":"Key events and figures","text":"China''s Four Great Inventions are papermaking, printing, gunpowder, and the compass. Papermaking came earlier, in the Han. Printing matured now: woodblock printing spread under the Tang, and Bi Sheng devised movable type around 1040 under the Song. Gunpowder, first used for fireworks and medicine, was turned to weapons by the late Tang and Song. The magnetic compass, known earlier, was first used for sea navigation in the Song, enabling long ocean voyages. The exam system was formalized under the Sui in 605 CE, expanded by the Tang, and flourished under the Song. The Song also saw Neo-Confucianism, reshaped by the scholar Zhu Xi, become the intellectual framework for later exams. The brilliant Song eventually fell to a rising power from the north - the Mongols."},{"heading":"Your turn","text":"1) Name the two most celebrated Tang poets. 2) List the Four Great Inventions. 3) Which invention was first used for sea navigation in the Song? 4) Who devised movable-type printing around 1040? 5) What did passing the civil-service exam make you? Answers: 1) Li Bai and Du Fu. 2) papermaking, printing, gunpowder, the compass. 3) the compass. 4) Bi Sheng. 5) a scholar-official, part of the bureaucracy that governed China."},{"heading":"Common mistakes and exit ticket","text":"Mistake: crediting all four great inventions to the Tang and Song; papermaking is older, a Han achievement. Mistake: thinking the exam made government fully equal - study demanded time and resources few poor families had, even if talent, not birth, was the official test. Exit: (a) Which dynasty is most famous for poetry, and which for commerce and invention? (b) What was the civil-service exam based on? Answers: the Tang for poetry, the Song for commerce and invention; mastery of the Confucian classics."}]}'::jsonb, null, 15),
  (8, 'The Yuan and the Ming', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how the Mongols conquered China to found the Yuan, and how the Ming restored native rule, sent great fleets abroad, and built the Forbidden City. Warm-up: China was now ruled by foreign conquerors for the first time. Would you expect foreign rulers to erase Chinese ways, or to adopt them to govern? Why?"},{"heading":"The idea","text":"In the thirteenth century the Mongols, united by Genghis Khan, swept across Asia. His grandson Kublai Khan completed the conquest of China and founded the Yuan dynasty (1271 to 1368), the first time all of China was ruled by foreign conquerors. Kublai moved his capital to Dadu, today''s Beijing, and governed a realm that was part of the largest contiguous land empire in history. The Mongol peace made travel safer, and the Venetian merchant Marco Polo famously claimed to have served at Kublai''s court, carrying tales of China''s wealth back to Europe. But Mongol rule, which often placed Mongols and foreigners above Chinese in status, grew resented, and rebellion, flood, and plague brought it down. A former peasant and monk, Zhu Yuanzhang, drove out the Mongols and founded the native Ming dynasty (1368 to 1644) as the Hongwu Emperor."},{"heading":"Key events and figures","text":"The Ming restored Confucian government and the examination system. Under the Yongle Emperor it reached outward: between 1405 and 1433 the admiral Zheng He led seven enormous treasure-fleet voyages across the Indian Ocean, reaching Southeast Asia, India, Arabia, and the coast of East Africa, decades before European voyages of a similar scale. Yongle also moved the capital to Beijing and built the Forbidden City, the vast walled palace complex completed around 1420 that housed emperors for the next five centuries. Later the Ming turned inward, halting the great voyages and rebuilding the Great Wall into the brick fortification familiar today. Internal strife and invasion eventually let yet another northern people, the Manchus, seize power - founding the Qing, the final dynasty."},{"heading":"Your turn","text":"1) Who founded the Yuan dynasty? 2) Which European merchant is said to have visited Kublai Khan''s court? 3) Who led the Ming treasure-fleet voyages, and roughly when? 4) What great palace complex did the Yongle Emperor build? 5) Which people founded the dynasty after the Ming? Answers: 1) Kublai Khan. 2) Marco Polo. 3) Admiral Zheng He, between 1405 and 1433. 4) the Forbidden City in Beijing. 5) the Manchus, who founded the Qing."},{"heading":"Common mistakes and exit ticket","text":"Mistake: thinking the Mongols ruled as nomads apart from China - Kublai Khan adopted a Chinese dynastic name, Yuan, and Chinese forms of government. Mistake: placing Zheng He''s voyages after Columbus; they came decades earlier, in the early 1400s, and on a far larger scale. Exit: (a) Put in order: Ming, Song, Yuan. (b) Name the Ming admiral and the palace built under the Yongle Emperor. Answers: Song, then Yuan, then Ming; Zheng He, and the Forbidden City."}]}'::jsonb, null, 14),
  (9, 'Key terms of imperial China', 'vocab', '{"items":[{"term":"dynasty","translation":"a sequence of rulers from the same family or line that holds power over a realm","example":"The Tang dynasty ruled China from 618 to 907 CE."},{"term":"Mandate of Heaven","translation":"the belief that Heaven grants the right to rule to a just leader and withdraws it from an unjust one","example":"Rebels argued that famine and revolt proved the emperor had lost the Mandate of Heaven."},{"term":"filial piety","translation":"the Confucian virtue of respect and devotion that children owe their parents and ancestors","example":"Filial piety required a son to honor his parents in life and to tend their graves after death."},{"term":"civil-service examination","translation":"a competitive written test on the Confucian classics used to select government officials by merit","example":"A farmer''s son who passed the civil-service examination could become a respected scholar-official."},{"term":"scholar-official (mandarin)","translation":"an educated administrator who passed the exams and governed on the emperor''s behalf","example":"The empire was run day to day by a class of scholar-officials, sometimes called mandarins."},{"term":"Silk Road","translation":"the network of overland and sea trade routes linking China with Central Asia, India, and the West","example":"Silk traveled west and Buddhism traveled east along the Silk Road."}]}'::jsonb, null, 10),
  (10, 'The Qing, the end of empire, and China''s legacy', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how the Qing became China''s last dynasty, why the two-thousand-year imperial system ended in 1912, and what imperial China left to the world. Warm-up: an empire that lasted millennia finally ended. What pressures, inside and outside, might topple a system that had survived so many earlier crises?"},{"heading":"The idea","text":"The Qing dynasty (1636, ruling all China from 1644, to 1912) was founded by the Manchus, a people from the northeast, making it the second dynasty of foreign conquerors after the Yuan. Under strong early emperors such as Kangxi and Qianlong the Qing expanded China to its greatest size and enjoyed long prosperity, while keeping Confucian government and the examination system. In the nineteenth century, however, the dynasty weakened under population pressure, internal rebellions such as the vast Taiping Rebellion, and the shock of industrial Western and Japanese powers. Defeats in the Opium Wars forced humiliating treaties and foreign concessions. Reform came too slowly, and in the Xinhai Revolution of 1911 the dynasty collapsed. In February 1912 the child emperor Puyi abdicated, ending not just the Qing but the entire imperial system that had run from 221 BCE - more than two thousand years - and China became a republic."},{"heading":"Key events and figures","text":"Daily life across these centuries rested on the family, farming, and the Confucian social order, with the scholar-official class above merchants and peasants, and women''s roles tightly constrained. Yet ordinary people enjoyed a rich material culture of tea, silk, porcelain - so prized abroad that fine china took its English name from the country itself. China''s lasting legacy is immense: the Four Great Inventions reshaped the world; Confucian ideas of merit, learning, and family still influence East Asia; and the written characters, cuisine, and philosophies spread across Korea, Japan, and Vietnam. The exam-based bureaucracy was studied and admired by later European reformers. Imperial China shows how a civilization can preserve a continuous identity across thousands of years and many dynasties, each claiming the Mandate of Heaven from the last."},{"heading":"Your turn","text":"1) Which people founded the Qing dynasty? 2) Name one pressure that weakened the Qing in the 1800s. 3) In what year did the last emperor abdicate? 4) Roughly how long did the whole imperial system last? 5) Give one lasting legacy of imperial China. Answers: 1) the Manchus. 2) any of: the Opium Wars, the Taiping Rebellion, foreign pressure, population strain. 3) 1912 (Puyi''s abdication). 4) about two thousand years, from 221 BCE to 1912 CE. 5) any of: the Four Great Inventions, Confucianism, the writing system, porcelain, the merit exam idea."},{"heading":"Common mistakes and exit ticket","text":"Mistake: calling the Ming the last dynasty - the Qing came after it and was the final one. Mistake: thinking 1912 ended only the Qing; it ended the entire imperial system stretching back to Qin Shi Huang in 221 BCE. Exit: (a) Name the first and the last imperial dynasties and the years the system began and ended. (b) Name two lasting legacies of imperial China. Answers: the Qin began it in 221 BCE and the Qing ended it in 1912; any two of the Four Great Inventions, Confucianism, the written script, porcelain, or the merit-based exam."}]}'::jsonb, null, 14)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0005-0000-4000-8000-00000000000d' and l.position = v.pos
);
